import React, { useState } from "react";

function Chatbot() {
  const [text, setText] = useState("");
  const [response, setResponse] = useState(null);
  const [recording, setRecording] = useState(false);
  const [mediaRecorder, setMediaRecorder] = useState(null);

  // 👉 ส่งข้อความ text ไป backend
  const handleSend = async () => {
    console.log("Sending to backend:", text);
    if (!text.trim()) return;
    const res = await fetch("/api/match", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text }),
    });
    const data = await res.json();
    setResponse(data);
  };

  // 🎙️ เริ่มอัดเสียง
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      const chunks = [];

      recorder.ondataavailable = (e) => chunks.push(e.data);
      recorder.onstop = async () => {
        const blob = new Blob(chunks, { type: "audio/webm" });
        const formData = new FormData();
        formData.append("file", blob, "voice.webm");

        const res = await fetch("/api/voice", {
          method: "POST",
          body: formData,
        });
        const data = await res.json();
        setResponse(data);
      };

      recorder.start();
      setMediaRecorder(recorder);
      setRecording(true);
    } catch (err) {
      console.error("Microphone error:", err);
      alert("Microphone not available or permission denied.");
    }
  };

  // ⏹️ หยุดอัดเสียง
  const stopRecording = () => {
    if (mediaRecorder) {
      mediaRecorder.stop();
      setRecording(false);
    }
  };

  return (
    <div style={{ padding: "20px", maxWidth: "600px", margin: "0 auto" }}>
      <h2>Symptom Matcher</h2>

      <div style={{ display: "flex", gap: "10px", marginBottom: "10px" }}>
        <input
          type="text"
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Enter your symptom..."
          style={{
            flexGrow: 1,
            padding: "10px",
            borderRadius: "6px",
            border: "1px solid #ccc",
          }}
        />
        <button
          onClick={handleSend}
          style={{ padding: "10px 20px", borderRadius: "6px" }}
        >
          Send
        </button>
        <button
          onClick={recording ? stopRecording : startRecording}
          style={{
            padding: "10px 20px",
            borderRadius: "6px",
            background: recording ? "red" : "lightgreen",
            color: recording ? "white" : "black",
          }}
        >
          {recording ? "Stop" : "🎤 Mic"}
        </button>
      </div>

      {response && (
        <div
          style={{
            marginTop: "20px",
            padding: "10px",
            borderRadius: "8px",
            background: "#f5f5f5",
            color: "#000",
          }}
        >
          <p>
            <b>Input:</b> {response.input || "Voice Input"}
          </p>

          {response.symptoms?.length > 0 && (
            <>
              <p>
                <b>Matched Symptoms:</b>
              </p>
              <ul>
                {response.symptoms.map((symptom) => (
                  <li key={symptom}>
                    {symptom}
                    {response.mapping && response.mapping[symptom] && (
                      <> → {response.mapping[symptom].join(", ")}</>
                    )}
                  </li>
                ))}
              </ul>
            </>
          )}

          {response.predictions?.length > 0 && (
            <>
              <p>
                <b>Predicted Diseases:</b>
              </p>
              <ul>
                {response.predictions.map((p, index) => (
                  <li key={index}>
                    {p.disease}: {p.score}
                  </li>
                ))}
              </ul>
            </>
          )}
        </div>
      )}
    </div>
  );
}

export default Chatbot;
